class Solution {
    public int countInRange(int[] nums, int lo, int hi) {
        if (lo > hi) {
            return 0;
        }
        int count = 0;
        for (int i = 0; i < nums.length - 1; i++) {
            if (nums[i] >= lo && nums[i] <= hi) {
                count++;
            }
        }
        return count;
    }
}

class Solution {
    public int countInRange(int[] nums, int lo, int hi) {
        if (lo > hi) {
            int t = lo;
            lo = hi;
            hi = t;
        }
        int count = 0;
        for (int v : nums) {
            if (v >= lo && v <= hi) {
                count++;
            }
        }
        return count;
    }
}
